<div class="page-heading"><div><div class="eyebrow">MOVIMENTAÇÕES AUDITÁVEIS</div><h1>Estoque</h1><p>Entradas, saídas e saldos com histórico permanente.</p></div><div class="page-actions"><a href="<?=e(url('materials'))?>" class="btn-aurora btn-outline-aurora">Catálogo de materiais</a></div></div>
<div class="grid-split"><div class="panel"><div class="panel-header"><h2>Últimas movimentações</h2><span class="tag">100 mais recentes</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Material</th><th>Movimento</th><th>Saldo</th><th>Motivo / Usuário</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><strong><?=e($m['material_name'])?></strong><small><?=e(date_time_br($m['created_at']))?></small></td><td><strong class="<?=$m['delta']>=0?'text-accent':'text-danger-aurora'?>"><?=$m['delta']>0?'+':''?><?=e(qty($m['delta']))?> <?=e($m['unit'])?></strong></td><td><?=e(qty($m['after_qty']))?></td><td><?=e($m['reason'])?><small><?=e($m['user_name'])?></small></td></tr><?php endforeach;?><?php if(!$movements):?><tr><td colspan="4" class="empty">Sem movimentações.</td></tr><?php endif;?></tbody></table></div></div>
<div><div class="panel panel-pad" style="margin-bottom:20px"><h2>Registrar movimentação</h2><p class="hint" style="margin-bottom:18px">Baixa manual, compra, devolução ou ajuste justificado.</p><?php if(allow(['production'])):?><form action="<?=e(url('stock.move'))?>" method="post"><?=csrf_field()?><input type="hidden" name="_back" value="stock"><div class="form-grid"><div class="field span-2"><label>Material *</label><select name="material_id" required><option value="">Selecione...</option><?php foreach($materials as $m):?><option value="<?=e($m['id'])?>"><?=e($m['name'])?> — <?=e(qty($m['stock']))?> <?=e($m['unit'])?></option><?php endforeach;?></select></div><div class="field"><label>Tipo</label><select name="type"><option value="in">Entrada (+)</option><option value="out">Saída (−)</option></select></div><div class="field"><label>Quantidade *</label><input name="quantity" type="number" min="0.001" step="0.001" required></div><div class="field span-2"><label>Motivo *</label><input name="reason" placeholder="Ex.: Compra de materiais para estoque" required></div></div><div class="form-footer"><button class="btn-aurora">Registrar movimentação</button></div></form><?php else:?><p class="hint">Seu perfil não tem acesso às alterações de estoque.</p><?php endif;?></div><div class="panel panel-pad"><h2>Alertas de estoque</h2><p class="hint" style="margin-bottom:12px">Materiais que atingiram o limite cadastrado.</p><?php $low=array_filter($materials,fn($m)=>(float)$m['stock']<=(float)$m['minimum_stock']);foreach($low as $m):?><div style="display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid var(--line)"><span><?=e($m['name'])?></span><strong class="text-danger-aurora"><?=e(qty($m['stock']))?> <?=e($m['unit'])?></strong></div><?php endforeach;?><?php if(!$low):?><div class="muted" style="padding:12px 0">Todos os materiais estão acima do mínimo.</div><?php endif;?></div></div></div>
